import {commerceConfig} from './commerce-config.mjs';
import {stages,stageLabels,previewShipping,validateAddress,quoteCheckout,completePreviewOrder,advancePreviewOrder,previewTracking,createManualPreviewOrder,submitManualPreview,approveManualPreview} from './commerce-model.mjs';
const rupees=p=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(p/100),when=s=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
export function createCheckout({getAccount=()=>null,openModal,getState,getBasket,commit,saveBag,esc,imageURL,icon,toast,copy}){
 let draft=null,session=null,latest=null,busy=false,info={mode:'manual_demo',provider:'manual_upi',ready:true,payment:{sample:true,upiId:'dripanddusk@example',payeeName:'Drip & Dusk (sample)'}},isAPI=commerceConfig.mode==='api';
 if(isAPI)info={mode:'loading',provider:'none',ready:false};
 const base=commerceConfig.apiBase.replace(/\/$/,'');
 async function api(path,{method='GET',body,token}={}){const r=await fetch(base+path,{method,signal:AbortSignal.timeout(15000),credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('Checkout service is unavailable. Please try again later.')}if(!r.ok)throw Object.assign(Error(data.error||'The request could not be completed.'),{status:r.status});return data;}
 function notice(){return `<div class="checkout-mode"><b>${info.provider==='manual_upi'?'Merchant UPI · sample checkout':info.provider==='razorpay'?'Razorpay test mode':'Checkout preview'}</b><span>${info.provider==='manual_upi'?'Demonstration only. Do not send money. The owner approves the payment before confirming an order.':'Test payments only. No real money is collected.'}</span></div>`}
 function steps(active){return `<ol class="checkout-progress" aria-label="Checkout progress">${['Delivery','Review & pay','Confirmation'].map((s,i)=>`<li class="${i===active?'current':i<active?'complete':''}" ${i===active?'aria-current="step"':''}><span>${i+1}</span>${s}</li>`).join('')}</ol>`}
 function summary(q){return `<aside class="checkout-summary"><p class="eyebrow">YOUR SELECTION</p>${q.lines.map(l=>`<div class="checkout-line"><img src="${imageURL(l.image)}" alt="${esc(l.name)}" width="54" height="65"><div><b>${esc(l.name)}</b><span>${l.size} ml · ${esc(l.format)} · Qty ${l.qty}</span></div><strong>${rupees(l.unitPaise*l.qty)}</strong></div>`).join('')}<dl class="checkout-totals"><div><dt>Subtotal</dt><dd>${rupees(q.subtotalPaise)}</dd></div><div><dt>${q.preview?'Sample delivery':'Delivery'}</dt><dd>${q.feePaise===null?'Calculated next':q.feePaise===0?'Included':rupees(q.feePaise)}</dd></div><div class="checkout-total"><dt>${q.feePaise===null?'Subtotal':'Total'}</dt><dd>${rupees(q.totalPaise)}</dd></div></dl><p class="fineprint">${q.deliveryLabel||'Delivery charges appear before payment.'}</p></aside>`}
 async function initialize(){if(!isAPI)return null;try{const [configuration,data]=await Promise.all([api('/api/config'),api('/api/catalogue')]);info=configuration;if(data.settings)commit({...getState(),settings:{...getState().settings,...data.settings}});return data.products}catch(e){info={mode:'unavailable',provider:'none',ready:false};toast('The live catalogue is temporarily unavailable. You can browse the sample collection; checkout is paused.');return null}}
 function open(){
  if(!getBasket().length)return toast('Add a bottle or decant to your bag first.');
  if(info.ready===false)return openModal('Checkout is not ready.',`${notice()}<p>The merchant’s payment and delivery setup still needs to be connected. You can continue browsing or contact the seller.</p><button class="btn outline" data-action="contact">Ask Drip & Dusk</button>`,'checkout');
  if(draft?.address&&!session&&!latest){address();return;}
  const sample={name:'Demo Customer',phone:'9999999999',line1:'12 Example Avenue',line2:'',city:'Pune',state:'Maharashtra',postcode:'411001'};
  draft={address:['preview','manual_demo'].includes(info.mode)?sample:{name:'',phone:'',line1:'',line2:'',city:'',state:'',postcode:''},consent:false,requestId:crypto.randomUUID(),quote:null};session=null;latest=null;address();
 }
 function address(error=''){
  let q;try{q=quoteCheckout(getState().products,getBasket(),'411001',previewShipping);q={...q,feePaise:null,totalPaise:q.subtotalPaise,deliveryLabel:''}}catch(e){return openModal('Review your bag.',`<p>${esc(e.message)}</p><button class="btn" data-action="basket">Back to bag</button>`,'checkout')}
  const a=draft.address;
  openModal('Make it yours.',`${notice()}${steps(0)}<div class="checkout-layout"><form id="delivery-form" class="checkout-form"><p class="eyebrow">THE DETAILS THAT GET IT TO YOU</p><h3>Where shall it go?</h3><p class="checkout-account-note">${getAccount()?.user?'Signed in as '+esc(getAccount().user.email):'Checking out as a guest. <a href="#account/checkout">Sign in — optional ↗</a>'}</p><div class="form-grid">${[['Full name','name','text',80],['Mobile number','phone','tel',16],['Street address','line1','text',160],['Apartment / landmark — optional','line2','text',160],['City','city','text',80],['State','state','text',80],['PIN code','postcode','text',6]].map(([label,key,type,max])=>`<label class="${['name','line1','line2'].includes(key)?'span-2':''}">${label}<input name="${key}" type="${type}" value="${esc(a[key])}" maxlength="${max}" ${key==='line2'?'':'required'} ${key==='postcode'?'inputmode="numeric" pattern="[1-9][0-9]{5}"':''} autocomplete="${{name:'name',phone:'tel',line1:'address-line1',line2:'address-line2',city:'address-level2',state:'address-level1',postcode:'postal-code'}[key]}"></label>`).join('')}<label>Country<input value="India" readonly aria-label="Country"></label></div><label class="checkout-consent"><input name="consent" type="checkbox" ${draft.consent?'checked':''}><span>I’d like the seller to send my confirmation and tracking link manually on WhatsApp.</span></label><p id="checkout-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" type="submit">Review delivery & total ↗</button><p class="fineprint">${['preview','manual_demo'].includes(info.mode)?'Example details stay in this checkout session and are not saved with demo orders.':'Your details are used to fulfil this order. WhatsApp updates are optional.'}</p></form>${summary(q)}</div>`,'checkout','DRIP & DUSK / CHECKOUT');
  document.querySelector('#delivery-form').addEventListener('input',e=>{if(['name','phone','line1','line2','city','state','postcode'].includes(e.target.name))draft.address[e.target.name]=e.target.value;if(e.target.name==='consent')draft.consent=e.target.checked});
  document.querySelector('#delivery-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.currentTarget);draft.address=Object.fromEntries(['name','phone','line1','line2','city','state','postcode'].map(k=>[k,String(f.get(k)||'')]));draft.consent=f.has('consent');busy=true;const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{draft.address=validateAddress(draft.address);draft.quote=isAPI?await api('/api/checkout/quote',{method:'POST',body:{basket:getBasket(),postcode:draft.address.postcode}}):quoteCheckout(getState().products,getBasket(),draft.address.postcode,previewShipping);busy=false;review()}catch(e){document.querySelector('#checkout-error').textContent=e.message;button.disabled=false}finally{busy=false}});
 }
 function review(error=''){
  const a=draft.address;
  openModal('One final look.',`${notice()}${steps(1)}<div class="checkout-layout"><section class="checkout-review"><p class="eyebrow">YOUR DELIVERY DETAILS</p><h3>${esc(a.name)}</h3><p>${esc(a.line1)}${a.line2?'<br>'+esc(a.line2):''}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.postcode)}<br>India · +${esc(a.phone)}</p><button class="text-link" data-action="checkout-address">Edit delivery details ↗</button><div class="checkout-payment"><p class="eyebrow">${info.provider==='manual_upi'?'MERCHANT UPI':'UPI OR CARD'}</p><h4>${info.provider==='manual_upi'?'A direct payment. A personal confirmation.':info.provider==='razorpay'?'Pay securely with Razorpay':'Payment preview'}</h4><p>${info.provider==='manual_upi'?'Create your sample order, review the merchant details, then submit a sample reference. Your order remains awaiting verification until the owner checks and approves it.':info.provider==='razorpay'?'Choose your payment method in the secure payment window. We confirm the order only after the server verifies a captured payment.':'The real Razorpay checkout will be available once the merchant’s test keys are connected. The buttons below let you review success and failure without charging anything.'}</p><p id="checkout-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" data-action="checkout-pay" ${busy?'disabled':''}>${info.provider==='manual_upi'?'Create sample UPI order':info.provider==='razorpay'?'Pay '+rupees(draft.quote.totalPaise):'Simulate successful payment'} ${icon('bag')}</button>${info.provider==='preview'?'<button class="text-link" data-action="checkout-fail">Simulate failed payment</button>':''}<p class="fineprint">${draft.consent?'WhatsApp updates requested.':'WhatsApp updates are switched off.'} ${info.mode==='preview'?'No message or shipment will be created.':''}</p></div></section>${summary(draft.quote)}</div>${session?`<p class="fineprint">Payment already started? <a class="text-link" href="#track/${esc(session.id)}/${esc(session.token)}">Open your private payment status ↗</a></p>`:''}`,'checkout','DRIP & DUSK / CHECKOUT');
 }
 async function pay(){
  if(busy||!draft?.quote)return;busy=true;document.querySelector('[data-action=checkout-pay]')?.setAttribute('disabled','');
  try{
   if(!isAPI){const result=(info.provider==='manual_upi'?createManualPreviewOrder:completePreviewOrder)(getState(),getBasket(),draft.quote,{requestId:draft.requestId,consent:draft.consent});if(!commit(result.state))throw Error('Could not save the demo order. Your bag has not been cleared.');saveBag([]);draft.address=null;latest=result.order;location.hash='track/'+latest.id+'/'+latest.token;return;}
   session??=await api('/api/orders',{method:'POST',body:{quoteId:draft.quote.quoteId,basket:getBasket(),address:draft.address,whatsappConsent:draft.consent,requestId:draft.requestId}});
   if(session.provider==='manual_upi'){saveBag([]);draft.address=null;location.hash='track/'+session.id+'/'+session.token;return;}
   if(session.status&&session.status!=='pending'){await paid();return;}
   if(session.provider==='preview'){await api('/api/orders/'+session.id+'/preview-payment',{method:'POST',body:{outcome:'success'},token:session.token});await paid();return;}
   if(!window.Razorpay)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=()=>reject(Error('The payment window could not load. Please try again.'));document.head.append(s)});
   const checkout=new window.Razorpay({key:session.keyId,amount:session.amount,currency:'INR',name:'Drip & Dusk',order_id:session.gatewayOrderId,prefill:{name:draft.address.name,contact:draft.address.phone},theme:{color:'#51412b'},handler:async result=>{try{await api('/api/orders/'+session.id+'/verify',{method:'POST',body:result,token:session.token});await paid()}catch(e){review(e.message)}},modal:{ondismiss:()=>{busy=false;review('Payment window closed. No order is confirmed until payment is verified.')}}});checkout.open();
  }catch(e){review(e.message)}finally{busy=false;document.querySelector('[data-action=checkout-pay]')?.removeAttribute('disabled')}
 }
 async function paid(){const result=await api('/api/orders/'+session.id,{token:session.token});if(stages.includes(result.status)||result.paymentStatus==='captured_unallocated'){saveBag([]);draft.address=null;const data=await api('/api/catalogue');commit({...getState(),products:data.products});}location.hash='track/'+session.id+'/'+session.token;}
 function trackingLink(o){const u=new URL(location.href);u.hash='track/'+encodeURIComponent(o.id)+'/'+encodeURIComponent(o.token);return u.href;}
 async function track(id,token){
  try{latest=isAPI?{...await api('/api/orders/'+encodeURIComponent(id),{token}),id,token}:previewTracking(getState(),id,token);if(location.hash!=='#track/'+id+'/'+token)return;renderTrack(latest);if(latest.paymentMethod==='manual_upi')bindManualForm(latest)}catch(e){if(location.hash!=='#track/'+id+'/'+token)return;openModal('Tracking link unavailable.',`<p>${esc(e.message)}</p><p class="fineprint">Check that you copied the complete tracking link. A demo link works only in the browser that created it.</p><button class="btn outline" data-action="contact">Ask Drip & Dusk</button>`,'tracking')}
 }
 function renderTrack(o){
  const n=stages.indexOf(o.status),manual=o.paymentMethod==='manual_upi',preview=o.mode==='preview'||o.mode==='manual_demo',message=`Drip & Dusk · ${o.ref}\nYour ${preview?'demo ':''}order is ${stageLabels[o.status]?.toLowerCase()||o.status}.\nTotal: ${rupees(o.totalPaise)}\nTrack: ${trackingLink(o)}`;
  openModal('Your fragrance journey.',`${preview?`<div class="checkout-mode"><b>${manual?'Sample UPI order':'Demo order'}</b><span>No money is collected and no message or shipment is sent. ${isAPI?'This is a local server test order.':'This demo tracking link works only in this browser.'}</span></div>`:info.mode==='sandbox'?'<div class="checkout-mode"><b>Razorpay test order</b><span>Test payment only. No real money was collected.</span></div>':''}<div class="order-heading"><div><p class="eyebrow">${esc(o.ref)}</p><h3>${esc(stageLabels[o.status]||o.status)}</h3><p>${o.status==='confirmed'?'Your selection is confirmed and ready for the next step.':o.status==='pending'?'Review the sample UPI details below. Payment has not been verified.':o.status==='awaiting_verification'?'Reference received. The owner must check the bank receipt before confirming your order.':o.status==='payment_review'?'Your payment needs the seller’s attention. Please contact Drip & Dusk.':'Follow your order’s progress below.'}</p></div><span class="order-total">${rupees(o.totalPaise)}</span></div>${manual?manualPayment(o):''}<ol class="order-timeline" aria-label="Order progress">${stages.map((stage,i)=>`<li class="${i<=n?'done':''} ${i===n?'current':''}" ${i===n?'aria-current="step"':''}><span>${i<n?'✓':i+1}</span><b>${stageLabels[stage]}</b><small>${o.events.find(e=>e.status===stage)?when(o.events.find(e=>e.status===stage).at):'Awaiting update'}</small></li>`).join('')}</ol><div class="tracking-columns"><section><h4>In your order</h4>${summary({...o,preview,deliveryLabel:o.deliveryLabel})}</section><section class="notification-card"><p class="eyebrow">WHATSAPP UPDATES</p><h4>${manual?'Personal updates':o.notificationStatus==='not_requested'?'Updates switched off':preview?'Message preview':'Order notifications'}</h4><p>${manual?'The seller can share your private tracking link manually through WhatsApp after approving the payment. Automatic WhatsApp messages are not enabled.':o.notificationStatus==='not_requested'?'You did not opt in to WhatsApp updates. Your tracking link still works.':preview?'This is the message the connected service will send after payment verification.':o.notificationStatus==='delivered'?'Your confirmation message was delivered.':o.notificationStatus==='submitted'?'Your confirmation was submitted to WhatsApp.':o.notificationStatus==='not_requested'?'You did not opt in to WhatsApp updates. Your tracking link still works.':'WhatsApp delivery is pending. Your confirmed order is saved independently of message delivery.'}</p>${preview&&!manual&&o.notificationStatus!=='not_requested'?`<pre class="order-message">${esc(message)}</pre>`:''}<p class="fineprint">${preview?(isAPI?'Use Owner studio to review this local test order.':'Use Owner studio → Demo orders to simulate packing, shipping and delivery.'):'Tracking changes when the connected courier or seller reports an update.'}</p><div class="order-tools"><button class="text-link" data-action="order-copy" data-id="${esc(o.id)}">Copy ${preview?'demo ':''}tracking link ↗</button><button class="text-link" data-action="order-refresh">Refresh status</button><button class="text-link" data-action="contact">Contact Drip & Dusk ${icon('chat')}</button></div></section></div>`,'tracking','DRIP & DUSK / ORDER TRACKING');
 }
 function admin(container){
  if(isAPI){serverAdmin(container);return;}
  const orders=getState().demoOrders||[];container.innerHTML=`<div class="notice"><strong>Demo orders only.</strong> These records stay in this browser. No address or phone number is saved, no payment is taken, and fulfilment buttons simulate courier updates.</div>${orders.length?orders.map(o=>`<article class="admin-order"><div><p class="eyebrow">${esc(o.ref)}</p><h3>${esc(stageLabels[o.status])}</h3><p>${o.lines.map(l=>esc(l.name)+' · '+l.size+' ml × '+l.qty).join('<br>')}</p><span>${rupees(o.totalPaise)} · ${when(o.createdAt)}</span></div><div class="admin-order-actions"><a class="btn outline" href="#track/${esc(o.id)}/${esc(o.token)}">View demo tracking</a>${['pending','awaiting_verification'].includes(o.status)?`<button class="btn" data-action="order-local-approve" data-id="${esc(o.id)}">Approve sample payment</button>`:stages.indexOf(o.status)>=0&&stages.indexOf(o.status)<3?`<button class="btn" data-action="order-advance" data-id="${esc(o.id)}" data-stage="${stages[stages.indexOf(o.status)+1]}">Simulate ${stages[stages.indexOf(o.status)+1]==='packed'?'packing':stages[stages.indexOf(o.status)+1]==='shipped'?'shipping':'delivery'}</button>`:''}</div></article>`).join(''):'<div class="empty-state"><h3>The next chapter starts with an order.</h3><p>Add a bottle or decant to the bag and try the checkout preview.</p><a class="btn" href="#collection">Explore fragrances ↗</a></div>'}`;
 }
 function manualPayment(o){
  if(!['pending','awaiting_verification'].includes(o.status))return '';
  const p=o.payment||info.payment||{},waiting=o.status==='awaiting_verification';
  return `<section class="upi-payment-card"><div><p class="eyebrow">${waiting?'REFERENCE SUBMITTED':'PAYMENT DETAILS / SAMPLE'}</p><h4>${waiting?'Awaiting the owner’s verification.':'Pay directly with merchant UPI.'}</h4><p>${waiting?'A reference is a claim of payment. Your order will be confirmed only after the owner checks the bank receipt.':'This is a sample merchant identity. Do not attempt a real payment.'}</p><dl><div><dt>Payee</dt><dd>${esc(p.payeeName||'Drip & Dusk (sample)')}</dd></div><div><dt>UPI ID</dt><dd>${esc(p.upiId||'dripanddusk@example')}</dd></div><div><dt>Order total</dt><dd>${rupees(o.totalPaise)}</dd></div></dl><p class="fineprint">${o.expiresAt?'Sample reservation expires '+esc(when(o.expiresAt))+'. ':''}No payment app is opened in this demo.</p></div><div class="upi-sample-mark" aria-label="Sample payment placeholder; no payment QR"><svg aria-hidden="true"><use href="#bottle-icon"/></svg><b>SAMPLE ONLY</b><span>Merchant QR goes here</span></div>${!waiting?`<form id="upi-reference-form" class="span-2"><label>Sample transaction reference<input name="reference" value="DEMO123456789" pattern="[A-Za-z0-9-]{6,40}" minlength="6" maxlength="40" required></label><p id="upi-error" class="form-error" role="alert"></p><button class="btn" type="submit">Submit reference for verification ↗</button><p class="fineprint">This action does not mark the order paid.</p></form>`:''}</section>`;
 }
 function bindManualForm(o){document.querySelector('#upi-reference-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const reference=String(new FormData(e.currentTarget).get('reference')).trim();if(isAPI)await api('/api/orders/'+o.id+'/payment-submission',{method:'POST',token:o.token,body:{reference}});else if(!commit(submitManualPreview(getState(),o.id,reference)))throw Error('Could not save this reference.');await track(o.id,o.token);}catch(e){const error=document.querySelector('#upi-error');if(error)error.textContent=e.message;}finally{button.disabled=false;}});}
 async function serverAdmin(container){
  try{const {orders}=await api('/api/admin/orders');container.innerHTML=`<div class="notice">Shared order management · ${esc(info.mode)} · Manual confirmations require checking the receipt in the bank or merchant app.</div>${orders.map(o=>{
   const next={confirmed:'packed',packed:'shipped',shipped:'delivered'}[o.status],manual=o.payment_method==='manual_upi';
   return `<article class="admin-order"><div><p class="eyebrow">${esc(o.ref)}</p><h3>${esc(stageLabels[o.status]||o.status)}</h3><p>${esc(o.customer.name)} · ${esc(o.customer.phone)}<br>${esc(o.customer.line1)}, ${esc(o.customer.city)} ${esc(o.customer.postcode)}</p><p>${o.lines.map(l=>esc(l.name)+' × '+l.qty).join(' · ')}</p><span>${rupees(o.totalPaise)}</span>${o.payment_reference?`<p>Customer reference: <b>${esc(o.payment_reference)}</b></p>`:''}<a class="text-link" href="${esc(o.trackingPath)}">Open private tracking ↗</a></div><div class="admin-order-actions">${manual&&['pending','awaiting_verification'].includes(o.status)?`<form class="manual-approval-form" data-order-id="${esc(o.id)}"><label>Bank receipt reference<input name="bankReference" placeholder="DEMO123456789" pattern="[A-Za-z0-9-]{6,40}" required></label><label>Amount received (₹)<input name="amount" type="number" min="1" step="0.01" value="${o.totalPaise/100}" required></label><label class="checkout-consent"><input name="checkedBank" type="checkbox" required><span>${info.mode==='manual_demo'?'Simulate checking the bank receipt for this sample order.':'I checked the money received in the bank or merchant app.'}</span></label><p class="form-error" role="alert"></p><button class="btn" type="submit">${info.mode==='manual_demo'?'Approve sample payment':'Approve payment'}</button></form><button class="text-link" data-action="order-server-cancel" data-id="${esc(o.id)}">Cancel unpaid order</button>`:next&&(manual||o.status==='confirmed')?`<label class="shipment-field">Courier shipment ID — optional<input data-shipment-id="${esc(o.id)}" maxlength="100" placeholder="From your courier account"></label><button class="btn" data-action="order-server-pack" data-stage="${next}" data-id="${esc(o.id)}">Mark ${stageLabels[next].toLowerCase()}</button>`:''}${o.payment_status==='captured'?`<button class="text-link" data-action="order-message-preview" data-path="${esc(o.trackingPath)}" data-ref="${esc(o.ref)}">Preview WhatsApp confirmation ↗</button>`:''}</div></article>`;
  }).join('')||'<p>No orders yet.</p>'}`;
   container.querySelectorAll('.manual-approval-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),button=form.querySelector('button');button.disabled=true;try{await api('/api/admin/orders/'+form.dataset.orderId+'/approve-payment',{method:'POST',body:{bankReference:String(f.get('bankReference')).trim(),amountPaise:Math.round(Number(f.get('amount'))*100),checkedBank:f.has('checkedBank')}});toast('Sample payment approved. Stock updated once.');admin(container);}catch(e){form.querySelector('.form-error').textContent=e.message;button.disabled=false;}}));
  }catch(e){if(getAccount()?.ownerRequired){container.innerHTML='<div class="notice">Owner access could not be verified. Sign in with the approved owner account to continue.</div><a class="btn" href="#account/admin">Owner sign-in ↗</a>';return;}container.innerHTML=`<form id="owner-login" class="settings-form"><h3>Owner sign-in.</h3><label>Owner access key<input name="token" type="password" autocomplete="current-password" required></label><p id="owner-login-error" class="form-error" role="alert"></p><button class="btn" type="submit">Sign in</button></form>`;container.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/login',{method:'POST',body:{token:new FormData(e.currentTarget).get('token')}});location.reload();}catch(e){container.querySelector('#owner-login-error').textContent=e.message;}});}
 }
 async function handle(action,el){
  if(action==='checkout-open'){if(location.hash==='#checkout')open();else location.hash='checkout';}
  if(action==='checkout-address'){if(!busy){session=null;draft.requestId=crypto.randomUUID();address()}}
  if(action==='checkout-pay')await pay();
  if(action==='checkout-fail'){if(busy)return;review('Payment failed in this preview. No order was confirmed and stock was not deducted. You can try again.');}
  if(action==='order-refresh'&&latest)await track(latest.id,latest.token);
  if(action==='order-copy'&&latest)copy(trackingLink(latest),'Tracking link copied.');
  if(action==='order-local-approve'){if(commit(approveManualPreview(getState(),el.dataset.id,'DEMO'+Date.now())))toast('Sample payment approved.');}
  if(action==='order-message-preview'){const u=new URL(location.href);u.hash=el.dataset.path.slice(1);openModal('Your confirmation, ready to share.',`<p>Sample message. Nothing is sent automatically.</p><textarea class="message-preview" readonly>${esc('Drip & Dusk · '+el.dataset.ref+'\nYour order is confirmed.\nTrack: '+u.href)}</textarea>`,'message');}
  if(action==='order-server-cancel'){await api('/api/admin/orders/'+el.dataset.id+'/cancel',{method:'POST',body:{}});admin(document.querySelector('#admin-content'));}
  if(action==='order-advance'){try{if(commit(advancePreviewOrder(getState(),el.dataset.id,el.dataset.stage)))toast('Demo order updated. No courier was contacted.')}catch(e){toast(e.message)}}
  if(action==='order-signout'){await api('/api/admin/logout',{method:'POST',body:{}});admin(document.querySelector('#admin-content'));}
  if(action==='order-server-pack'){try{await api('/api/admin/orders/'+el.dataset.id+'/status',{method:'POST',body:{status:el.dataset.stage||'packed',shipmentId:document.querySelector('[data-shipment-id="'+el.dataset.id+'"]')?.value.trim()||''}});admin(document.querySelector('#admin-content'))}catch(e){toast(e.message)}}
 }
 return {initialize,open,track,handle,admin,get connected(){return isAPI},get mode(){return info.mode},api};
}
